// Mini @for: reuse rows by track key, create new ones only when the key is new.
// Time O(N) per update, space O(N).
function render(oldRows, items, track) {
  const byKey = new Map(oldRows.map(r => [r.key, r]));
  let created = 0, reused = 0, updated = 0;
  const rows = items.map((item, i) => {
    const key = track(item, i);
    const row = byKey.get(key);
    if (row) {
      reused++;
      if (row.item !== item) { row.item = item; updated++; } // same row, new data
      return row;
    }
    created++;
    return { key, item }; // a brand new "DOM node"
  });
  return { rows, created, reused, updated };
}

const a = { id: 1, name: 'Ann' }, b = { id: 2, name: 'Bob' }, c = { id: 3, name: 'Cy' };
