}

// Dev mode runs each binding twice. If the value changed between passes -> NG0100.
function checkNoChanges(bindings) {
  const first = bindings.map(b => b());      // normal change detection pass
  const second = bindings.map(b => b());     // dev-only verification pass
  first.forEach((v, i) => {
    if (v !== second[i]) {
      console.log('NG0100: binding ' + i + ' was ' + JSON.stringify(v) + ' now ' + JSON.stringify(second[i]));
    } else {
      console.log('binding ' + i + ' stable: ' + JSON.stringify(v));
    }
  });
}

