// Pure pipe = memoised function: re-run only if the input reference changes.
function pureCall(fn) {
  let lastIn, lastOut, has = false, runs = 0;
  const call = x => { if (!has || x !== lastIn) { lastIn = x; lastOut = fn(x); has = true; runs++; } return lastOut; };
  call.runs = () => runs;
  return call;
}
const sortPipe = arr => [...arr].sort((a, b) => a - b);

const pure = pureCall(sortPipe);
let list = [3, 1, 2];
for (let cycle = 0; cycle < 3; cycle++) pure(list);       // 3 change detections
console.log('pure, same array, 3 cycles -> runs:', pure.runs(), 'result:', pure(list));

list.push(0); // mutation: same reference
console.log('after push(0), pure shows:', JSON.stringify(pure(list)), '(stale!)');

list = [...list];  // immutable update: new reference
console.log('after new array, pure shows:', JSON.stringify(pure(list)), 'runs:', pure.runs());

