// What *appRepeat="3" does: TemplateRef = blueprint, ViewContainerRef = insertion point.
class ViewContainerRef {
  constructor() { this.views = []; }
  createEmbeddedView(tpl, ctx) { this.views.push(tpl(ctx)); }
  clear() { this.views = []; }
}
class AppRepeat {
  constructor(tpl, vcr) { this.tpl = tpl; this.vcr = vcr; }
  set appRepeat(n) {                       // runs when the bound value changes
    this.vcr.clear();                      // drop old views
    for (let i = 0; i < n; i++) this.vcr.createEmbeddedView(this.tpl, { $implicit: i, index: i });
  }
}

