// Tiny signal / computed / effect: only dependents of a changed signal re-run.
let active = null;
function signal(v) {
  const subs = new Set();
  const s = () => { if (active) subs.add(active); return v; };
  s.set = nv => { if (nv !== v) { v = nv; [...subs].forEach(fn => fn()); } };
  return s;
}
function effect(fn) { const run = () => { active = run; fn(); active = null; }; run(); }
function computed(fn) {
  const out = signal(undefined);
  effect(() => out.set(fn()));
  return out;
}

const price = signal(10), qty = signal(2), name = signal('Pen');
const total = computed(() => price() * qty());
let totalRenders = 0, nameRenders = 0;
effect(() => { totalRenders++; console.log('total view:', total()); });
effect(() => { nameRenders++; console.log('name view: ', name()); });

